-- 0141: opposites of the Ghāfir 40:2–3 roots (30-KIN, ar_ling_root_didd), checked against the lexicons and Lane.
-- The 38 unpromoted didd facts (ar_ling_lexicon_fact) group into 9 pairs; the books also state pairs the facts
-- missed (some only under the OTHER root: عِزّ↔ذُلّ, شَدّ↔حَلّ, نُزول↔ارتحال). 15 promoted, each with its books
-- (fact ids, block ids, pages) and its Qurʾān verse where one holds both sides (display_json.quran, needles
-- checked against qr_ayah.text_uthmani). Two kinds kept apart: antonym (two words) vs addad_internal (one word
-- with two opposite meanings, the classical aḍdād); Qurʾān-only pairs as antithetical_pair.
-- Fixes to the 8 existing rows: طُول↔عَرْض is a contrast (books say خلاف, not نقيض); كتب↔محو IS stated
-- (al-Rāghib, al-Qāmūs); كتب↔نشر is Ibn Sīdah's, a contrast; كتب↔فتق has no source → rejected.
-- Not promoted: نزل↔صعد (no book; they pair صعود with هبوط), نزل↔عرج (Qurʾān only, 34:2 — held), side senses.
-- No opposite in any book: توب, صير, اله; ذنب as "sin".
-- Every row gets the GLOBAL root ids: root_id, and antonym_root_id (new).
ALTER TABLE ar_ling_root_didd ADD COLUMN antonym_root_id TEXT REFERENCES ar_ling_roots(id);
UPDATE ar_ling_root_didd SET source_ref = source_ref || '; Lane blk_lane_10e0dabdce36ac12 p.1518 («تَشْدِيدٌ is the contr. of تَخْفِيفٌ»)' WHERE id = 'AN:شدد:2' AND source_ref NOT LIKE '%blk_lane_10e0dabdce36ac12%';
UPDATE ar_ling_root_didd SET relation_kind = 'contrast', antonym_en = 'width (the other direction)', confidence = 0.85, source_ref = 'lf_70077406b07dd2ec (Ṣiḥāḥ blk_sih_ebfcdd70eaeb00e6 p.3472); lf_307cc08f58eba8db (Tāj blk_taj_3038bea487fcb9fa p.390); Maqāyīs blk_mqy_a2bf5e7a3a2e79d3 p.61; Lane blk_lane_9893aadec3455a6a p.1896', note_en = 'Length ↔ width: two directions, not opposite amounts. The books say خلاف, never نقيض. Lane and Tāj give both: عَرْض (al-Ṣiḥāḥ) and قِصَر (al-Muḥkam).' WHERE id = 'AN:طول:2';
UPDATE ar_ling_root_didd SET relation_kind = 'antonym', generated_by = 'source_stated', confidence = 0.85, source_ref = 'al-Rāghib blk_mfr_1fa7e4a6cb358c02 p.699; lf_197dec6d2ad17185 (Qāmūs, art. لمق: «الكتابة، والمحو، ضدّ»); Qurʾān 13:39', note_en = 'Writing down ↔ erasing. al-Rāghib: «ويعبّر عن الإيجاد بالكتابة، وعن الإزالة والإفناء بالمحو» (13:38–39).', display_json = '{"quran":[{"surah":13,"ayah":39,"needle":"يمحوا الله ما يشاء ويثبت"}]}' WHERE id = 'DID:كتب:محو';
UPDATE ar_ling_root_didd SET status = 'rejected', note_en = 'Rejected (0141): no book pairs كتب with فتق; it was built from the stitching sense.' WHERE id = 'DID:كتب:فتق';
UPDATE ar_ling_root_didd SET relation_kind = 'contrast', confidence = 0.6, source_ref = 'Ibn Sīdah, al-Muḥkam blk_mhk_ktb_p25 («ما جُمِع فلم يُنشَر»), quoted in Lisān blk_lsn_e2c3ceaec7971e76 p.698', note_en = 'Gathered ↔ scattered. A definition by what it is not (al-Muḥkam), not a stated opposite. al-Ṣiḥāḥ only has «الكتيبة: الجيش».' WHERE id = 'DID:كتب:نشر';
UPDATE ar_ling_root_didd SET source_ref = 'raghib_mufradat blk_mfr_aa94ca778b470433, blk_mfr_165e9b1503036d02 p.699' WHERE id = 'DID:كتب:اغفل';
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:شدد:حلل', 'شدد', 'الحَلّ', 'حلل', 'untying, loosening', 'antonym', 3, 'lf_53b2dc27c0eda440 (Lisān blk_lsn_7b61216eedfac98a p.5345); lf_24d704f6ddafe5d5 (Tāj blk_taj_9414aca952293ab6 p.222); lf_f96ba1fba561352a (Qāmūs blk_qms_edf13af24d81d9d4); Lane blk_lane_10e850f964616fd7 p.5', 'live', 0.85, 'source_stated', 'Tying fast ↔ untying. Stated under حلل — Lane: «contr. of شَدٌّ».', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:شدد:ضعف', 'شدد', 'الضَّعْف', 'ضعف', 'weakness', 'antonym', 4, 'Lane blk_lane_3fbac6b289ec3314 p.1519 (مُشِدّ «contr. of مُضْعِفٌ»); Lisān blk_lsn_072c26a8eb40a76d p.1674; lf_3c12772286c35d9b (Tāj blk_taj_850c328d34f45dfa p.348)', 'live', 0.8, 'source_stated', 'Strength ↔ weakness (from the hadith «يرد مشدّهم على مضعفهم»).', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:شدد:رقق', 'شدد', 'الرِّقَّة', 'رقق', 'tenderness', 'antonym', 5, 'lf_69682da9a31da97f (Lisān blk_lsn_b577597c87247e2e p.4791)', 'live', 0.7, 'source_stated', 'Hardness of heart ↔ tenderness. Stated once, under رقق: «الرقة ضد القسوة والشدة».', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:علم:جهل', 'علم', 'الجَهْل', 'جهل', 'ignorance, not knowing', 'antonym', 1, 'lf_903edadc3e620aea (Lisān blk_lsn_f086f736f994fec6 p.1751); al-ʿAyn blk_kay_ilm_p1 p.507; Maqāyīs blk_mqy_e6726dced7f84bb0 p.21; Jamhara blk_jam_alm_p3 p.948; Tāj blk_taj_352fffe7455a99b5 p.127; lf_1130cdd4bcbf874c (Ṣiḥāḥ blk_sih_83f7b71dbac1c037 p.3296); Lane blk_lane_928e15b100036d89 p.477', 'live', 0.97, 'source_stated', 'Knowing ↔ not knowing. Stated by al-Khalīl, Ibn Fāris, Ibn Durayd, al-Jawharī, Lisān, Tāj and Lane (art. جهل).', '{"quran": [{"surah": 46, "ayah": 23, "needle": "انما العلم عند الله"}, {"surah": 46, "ayah": 23, "needle": "قوما تجهلون"}]}');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:علم:جهل:2', 'علم', 'المَجْهَل', 'جهل', 'unmarked, trackless land', 'antonym', 2, 'Maqāyīs blk_mqy_b960860ea0b9399e p.21; lf_6919800e30976bda (Lane blk_lane_fa484467c59064d6 p.2141)', 'live', 0.85, 'source_stated', 'Land with waymarks (مَعْلَم) ↔ trackless land.', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:عزز:ذلل', 'عزز', 'الذُّلّ', 'ذلل', 'humiliation, lowliness', 'antonym', 1, 'Ṣiḥāḥ blk_sih_d93f7c7a2b6d49f4 p.1751; Lisān blk_lsn_ea8cef1094b10396 p.2958; Maqāyīs blk_mqy_0460496cceae2186 p.13; lf_3ea526ef48650090 (Ṣiḥāḥ blk_sih_9b5a20b727611ff7 p.3372); lf_0378d5ebeddcb0c4 (Lisān blk_lsn_3d566c004da2ea47 p.5436); Lane blk_lane_62ff752766261f2d p.2031', 'live', 0.95, 'source_stated', 'Might and honour ↔ humiliation. Also 63:8 (الأعزّ / الأذلّ), 5:54, 27:34.', '{"quran": [{"surah": 3, "ayah": 26, "needle": "وتعز من تشاء وتذل من تشاء"}]}');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:عزز:هون', 'عزز', 'الهَوَان', 'هون', 'disgrace', 'antonym', 2, 'lf_b158b4cee3cf6410 (Lisān blk_lsn_397fbf78cf4ff3cc p.6999)', 'live', 0.8, 'source_stated', 'Honour ↔ disgrace. Stated as نقيض, under هون.', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:عزز:عزز', 'عزز', 'عَزَّ (ضَعُفَ)', 'عزز', 'also: became weak', 'addad_internal', 3, 'Miṣbāḥ blk_msb_1ebb65d597866856 p.2023 («فيكون من الأضداد»); Lane blk_lane_b3e879060e3fad9e p.2031', 'live', 0.75, 'source_stated', 'One word, two opposite meanings: عَزَّ = was strong, and also was weak.', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:غفر:غفر', 'غفر', 'غَفِرَ الجُرْحُ (نُكِسَ)', 'غفر', 'also: a wound reopened', 'addad_internal', 2, 'lf_1dc41428332355a3 (Tāj blk_taj_ed805b81471b9427 p.252, Ibn al-Qaṭṭāʿ «وهو من الأضداد»); Ṣiḥāḥ blk_sih_c7bd163d5495ce3a p.1528; Lisān blk_lsn_cb9134cb8341888a p.480; Maqāyīs blk_mqy_5625f6b80feeadad p.73; Lane blk_lane_1e9a41a18d15eb45 p.2273', 'live', 0.7, 'source_stated', 'One word, two opposite meanings, said of a wound: healed, and broke open again. A side sense, not forgiving; Ibn Fāris calls it rare (شاذّ).', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:غفر:عذب', 'غفر', 'العَذَاب', 'عذب', 'punishment', 'antithetical_pair', 1, 'Qurʾān 2:284 (also 3:129, 5:18, 5:40, 48:14); al-Rāghib blk_mfr_640b1dae79c8a58e p.609 («أن يصون العبد من أن يمسه العذاب»)', 'live', 0.8, 'source_stated', 'No lexicon calls them opposites; the Qurʾān sets them side by side, and al-Rāghib defines forgiving as keeping a person from punishment.', '{"quran": [{"surah": 2, "ayah": 284, "needle": "فيغفر لمن يشاء ويعذب من يشاء"}]}');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:ذنب:راس', 'ذنب', 'الرَّأْس', 'راس', 'head (vs. tail)', 'contrast', 1, 'Lisān blk_lsn_066090792a7bb3c0 p.389 («كأنهم في مقابل الرؤوس»); lf_bbc6211c93ca67a3 (Lane blk_lane_9144bfa27d40cab9 p.994); Lane blk_lane_93ff092dedcd53f9 p.980', 'live', 0.7, 'source_stated', 'The tail sense: followers (أذناب) ↔ leaders (رؤوس). No book gives an opposite for ذَنْب, sin.', NULL);
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:قبل:دبر', 'قبل', 'أَدْبَرَ', 'دبر', 'turn back, retreat', 'antonym', 1, 'lf_b7be198d791ede62 (Ṣiḥāḥ p.3555); lf_b4958fc3b76aad04, lf_c7ba2f23cfbda300, lf_63e60a7968f0d71c, lf_66550f516069d6f9 (Lisān p.1132); lf_4e700546d093884b, lf_094229e6f85a6ee3 (Qāmūs); lf_2bbc55f46730dbcb (Tāj p.218); lf_88c6354aab3b29bd (Ṣiḥāḥ); lf_6963c5a6f438df04, lf_b8deb361e4b50896, lf_5c5583e1c59f360e (Lane p.2983)', 'live', 0.97, 'source_stated', 'Coming forward, facing ↔ turning back. Also اِسْتَقْبَلَ ↔ اِسْتَدْبَرَ.', '{"quran": [{"surah": 28, "ayah": 31, "needle": "ولي مدبرا"}, {"surah": 28, "ayah": 31, "needle": "اقبل ولا تخف"}]}');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:قبل:بعد', 'قبل', 'بَعْدُ', 'بعد', 'after', 'antonym', 2, 'lf_e300b47a4118d777 (Ṣiḥāḥ blk_sih_bfaf418e40be4542 p.3555); lf_367a37d930c8e186 (Lisān p.1132); lf_9baf770639e6330b (Tāj p.206); lf_ca425a0c8aaf440c (Qāmūs); lf_ee543c820950d4b3 (Lane blk_lane_ffaad18da1ba4d9e p.2983); Miṣbāḥ blk_msb_8c771491d242b0d1 p.2421; Maqāyīs blk_mqy_eb2a54bd02310019 p.11', 'live', 0.97, 'source_stated', 'Before ↔ after. Abū Ḥātim (Tāj blk_taj_5c3158ce8c5948a5 p.440) even counts قبل/بعد among words with two opposite meanings (79:30).', '{"quran": [{"surah": 30, "ayah": 4, "needle": "لله الامر من قبل ومن بعد"}]}');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:قبل:دبر:2', 'قبل', 'الدُّبُر', 'دبر', 'the back, rear', 'antonym', 3, 'lf_c2a6dc613dce3781 (Ṣiḥāḥ p.3555); lf_51fed38415e2852f, lf_fdb1dac289dc8bef (Lisān p.1132); lf_8c8e1a7489bbf242, lf_e03a926cd527e22a (Tāj); lf_85c36d9c305550d5 (Qāmūs); al-ʿAyn blk_kay_0046863c6cd9a58b p.1738; Maqāyīs blk_mqy_de62875efd1ff29c p.11; Lane blk_lane_9ce9c17d6158e32f p.2984', 'live', 0.9, 'source_stated', 'Front ↔ back. Includes المُقابَل ↔ المُدابَر and القِبْلة ↔ الدِّبْرة. In the Qurʾān across two verses: 12:26 «من قُبُل» and 12:27 «من دُبُر».', '{"quran": [{"surah": 12, "ayah": 26, "needle": "قد من قبل"}, {"surah": 12, "ayah": 27, "needle": "قد من دبر"}]}');
INSERT OR IGNORE INTO ar_ling_root_didd (id, root_norm, antonym_ar, antonym_root, antonym_en, relation_kind, sort_order, source_ref, status, confidence, generated_by, note_en, display_json) VALUES ('DID:نزل:رحل', 'نزل', 'الارْتِحَال', 'رحل', 'setting off, departing', 'antonym', 1, 'lf_3897716f852fa695 (Lisān blk_lsn_9d484f55bccbd710 p.5345, under حلل: «نزول القوم بمحلة وهو نقيض الارتحال»); Ṣiḥāḥ blk_sih_e3b06a4eae589f60 p.3622; Lisān blk_lsn_584e798b850957b8 p.3765', 'live', 0.75, 'source_stated', 'Stopping to settle in a place ↔ setting off. Not صَعِدَ — no book pairs it with نزل.', NULL);
UPDATE ar_ling_root_didd SET root_id = (SELECT r.id FROM ar_ling_roots r WHERE r.root_normalized = ar_ling_root_didd.root_norm) WHERE root_id IS NULL AND (SELECT count(*) FROM ar_ling_roots r WHERE r.root_normalized = ar_ling_root_didd.root_norm) = 1;
UPDATE ar_ling_root_didd SET antonym_root_id = (SELECT r.id FROM ar_ling_roots r WHERE r.root_normalized = ar_ling_root_didd.antonym_root) WHERE antonym_root_id IS NULL AND (SELECT count(*) FROM ar_ling_roots r WHERE r.root_normalized = ar_ling_root_didd.antonym_root) = 1;
